namespace NetSuiteIntegration.Infrastructure.Configuration
{
    public class NetSuiteOptions
    {
        public string AccountId { get; set; } = string.Empty;
        public string BaseUrl { get; set; } = string.Empty;
        public bool UseMock { get; set; } = true;

        // OAuth 2.0 application information
        public string ClientId { get; set; } = string.Empty;

        // Certificate ID generated by NetSuite
        public string CertificateId { get; set; } = string.Empty;

        // Local path to the private key used for JWT signing
        public string PrivateKeyPath { get; set; } = string.Empty;

        // OAuth scope required for REST Web Services
        public string Scope { get; set; } = "rest_webservices";
    }
}
